def shallow_equal(obj_a, obj_b) -> bool:
    if obj_a is obj_b:
        return True
    if obj_a is None or obj_b is None:
        return False
    if type(obj_a) != type(obj_b):
        return False
    if isinstance(obj_a, dict):
        if set(obj_a.keys()) != set(obj_b.keys()):
            return False
        return all(obj_a[k] is obj_b[k] or obj_a[k] == obj_b[k] for k in obj_a if not isinstance(obj_a[k], (dict, list)))
    return obj_a == obj_b

def deep_equal(obj_a, obj_b) -> bool:
    if obj_a is obj_b:
        return True
    if type(obj_a) != type(obj_b):
        return False
    if obj_a is None or obj_b is None:
        return obj_a is obj_b
    if isinstance(obj_a, dict):
        if set(obj_a.keys()) != set(obj_b.keys()):
            return False
        return all(deep_equal(obj_a[k], obj_b[k]) for k in obj_a)
    if isinstance(obj_a, (list, tuple)):
        if len(obj_a) != len(obj_b):
            return False
        return all(deep_equal(a, b) for a, b in zip(obj_a, obj_b))
    return obj_a == obj_b

def create_selector(*args):
    input_selectors = args[:-1]
    result_fn = args[-1]
    last_inputs = [None]
    last_result = [None]

    def selector(state):
        inputs = tuple(s(state) for s in input_selectors)
        if last_inputs[0] is not None and inputs == last_inputs[0]:
            return last_result[0]
        last_inputs[0] = inputs
        last_result[0] = result_fn(*inputs)
        return last_result[0]

    return selector

