function shallowEqual(objA, objB) {
  if (Object.is(objA, objB)) return true;
  if (typeof objA !== 'object' || typeof objB !== 'object') return false;
  if (objA === null || objB === null) return false;

  const keysA = Object.keys(objA);
  const keysB = Object.keys(objB);
  if (keysA.length !== keysB.length) return false;

  return keysA.every(key => 
    Object.prototype.hasOwnProperty.call(objB, key) && Object.is(objA[key], objB[key])
  );
}

function deepEqual(objA, objB) {
  if (Object.is(objA, objB)) return true;
  if (typeof objA !== typeof objB) return false;
  if (objA === null || objB === null) return objA === objB;
  if (typeof objA !== 'object') return false;

  if (Array.isArray(objA) !== Array.isArray(objB)) return false;
  if (Array.isArray(objA)) {
    if (objA.length !== objB.length) return false;
    return objA.every((val, i) => deepEqual(val, objB[i]));
  }

  const keysA = Object.keys(objA);
  const keysB = Object.keys(objB);
  if (keysA.length !== keysB.length) return false;
  return keysA.every(key => deepEqual(objA[key], objB[key]));
}

function createSelector(...args) {
  const resultFn = args.pop();
  const inputSelectors = args;
  let lastInputs = null;
  let lastResult = null;

  return function(state) {
    const inputs = inputSelectors.map(sel => sel(state));
    if (lastInputs && inputs.every((val, i) => Object.is(val, lastInputs[i]))) {
      return lastResult;
    }
    lastInputs = inputs;
    lastResult = resultFn(...inputs);
    return lastResult;
  };
}
